import {indicators,periodLabel,numberLabel} from './observatorio-economy-data.mjs';
export function studySeries(rows){let ema=null;return rows.map((r,i)=>{const values=rows.slice(Math.max(0,i-19),i+1).map(x=>x.value),sma20=values.length===20?values.reduce((s,v)=>s+v,0)/20:null,sma50=i>=49?rows.slice(i-49,i+1).reduce((s,v)=>s+v.value,0)/50:null;if(i===19)ema=sma20;else if(i>19)ema=r.value*2/21+ema*19/21;const sd=sma20===null?null:Math.sqrt(values.reduce((s,v)=>s+(v-sma20)**2,0)/20);let rsi=null;if(i>=14){let gains=0,losses=0;for(let j=i-13;j<=i;j++){const delta=rows[j].value-rows[j-1].value;gains+=Math.max(0,delta);losses+=Math.max(0,-delta);}rsi=gains+losses===0?50:losses===0?100:100-100/(1+gains/losses);}return {...r,sma20,sma50,ema20:i>=19?ema:null,upper:sd===null?null:sma20+2*sd,lower:sd===null?null:sma20-2*sd,rsi};});}
export function aggregateReferences(rows,interval='daily'){
 const grouped=new Map();for(const r of rows){let key=r.date;if(interval==='monthly')key=r.date.slice(0,7);if(interval==='weekly'){const date=new Date(r.date+'T12:00:00Z');date.setUTCDate(date.getUTCDate()-(date.getUTCDay()+6)%7);key=date.toISOString().slice(0,10);}let bucket=grouped.get(key);if(!bucket){bucket={key,start:r.date,date:r.date,open:r.value,high:r.value,low:r.value,close:r.value,count:0};grouped.set(key,bucket);}Object.assign(bucket,{date:r.date,close:r.value,high:Math.max(bucket.high,r.value),low:Math.min(bucket.low,r.value),count:bucket.count+1,study:r});}return [...grouped.values()];
}
export function timePositions(rows,left,right){const start=Date.parse(rows[0]?.date),end=Date.parse(rows.at(-1)?.date);return rows.map(r=>start===end?(left+right)/2:left+(Date.parse(r.date)-start)/(end-start)*(right-left));}
export const studies={sma20:'Media 20',sma50:'Media 50',ema20:'EMA 20',bands:'Bandas 20 · 2σ',rsi:'RSI simple 14'};
export function advancedChart(d,visible,options,esc){
 const market=['dolar','cobre'].includes(d.id),enabled=market?options.studies:[],interval=market?options.interval:'daily',style=market&&interval!=='daily'?options.style:'line';
 const all=studySeries(d.series.filter(r=>r.date<=(d.date.length===7?d.date+'-01':d.date))),lookup=new Map(all.map(r=>[r.date,r]));const rows=visible.map(r=>({...r,...lookup.get(r.date)}));const buckets=aggregateReferences(rows,interval);if(!buckets.length)return '<p>No hay observaciones en este período.</p>';
 const w=760,h=330,left=76,right=20,top=22,bottom=42,values=buckets.flatMap(b=>[b.low,b.high,...enabled.filter(k=>k!=='rsi'&&k!=='bands').map(k=>b.study[k]),...(enabled.includes('bands')?[b.study.lower,b.study.upper]:[])]).filter(Number.isFinite),lo=Math.min(...values),hi=Math.max(...values),pad=(hi-lo)*.08||Math.max(Math.abs(lo)*.02,.1),min=lo-pad,max=hi+pad,positions=timePositions(buckets,left+10,w-right-10),x=i=>positions[i],y=v=>top+(max-v)/(max-min)*(h-top-bottom),fmt=v=>new Intl.NumberFormat('es-CL',{maximumFractionDigits:2}).format(v);
 const path=(key,scale=y)=>{let started=false;return buckets.map((b,i)=>{const v=key==='close'?b.close:b.study[key];if(!Number.isFinite(v)){started=false;return '';}const part=started?(d.id==='tpm'&&key==='close'?`H${x(i)}V${scale(v)}`:`L${x(i)},${scale(v)}`):`M${x(i)},${scale(v)}`;started=true;return part;}).join(' ');};
 const colors={sma20:'#bd651d',sma50:'#665ac7',ema20:'#227eb5',upper:'#86939a',lower:'#86939a'};
 const price=style==='candles'?buckets.map((b,i)=>{const color=b.close>=b.open?'#147360':'#bf4b45',bw=Math.max(1,Math.min(18,(w-left-right)/buckets.length*.65));return `<g><title>${esc(b.start)} – ${esc(b.date)}: primero ${fmt(b.open)}, máximo ${fmt(b.high)}, mínimo ${fmt(b.low)}, último ${fmt(b.close)} · ${b.count} referencias</title><line x1="${x(i)}" x2="${x(i)}" y1="${y(b.high)}" y2="${y(b.low)}" stroke="${color}"/><rect x="${x(i)-bw/2}" y="${Math.min(y(b.open),y(b.close))}" width="${bw}" height="${Math.max(1,Math.abs(y(b.open)-y(b.close)))}" fill="${color}"/></g>`;}).join(''):`<path data-econ-line d="${path('close')}" stroke="#147360" stroke-width="2.4" fill="none"/>`;
 const overlay=Object.entries(colors).filter(([key])=>enabled.includes(key)||enabled.includes('bands')&&['upper','lower'].includes(key)).map(([key,color])=>`<path data-study="${key}" d="${path(key)}" fill="none" stroke="${color}" stroke-width="1.8" ${['upper','lower'].includes(key)?'stroke-dasharray="5 4"':''}/>`).join('');
 return `<div class="econ-plot"><svg class="econ-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(indicators[d.id].name)} · ${style==='candles'?'Velas de referencias':'Línea'} · ${buckets.length} períodos">${Array.from({length:5},(_,i)=>{const v=min+(max-min)*i/4;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#dde6e1"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`;}).join('')}${price}${style==='line'&&buckets.length===1?`<circle cx="${x(0)}" cy="${y(buckets[0].close)}" r="4" fill="#147360"/>`:''}${overlay}<text x="${left}" y="${h-10}">${esc(buckets[0].start)}</text><text x="${w-right}" y="${h-10}" text-anchor="end">${esc(buckets.at(-1).date)}</text></svg></div>
 ${enabled.includes('rsi')?`<div class="econ-plot"><svg class="econ-rsi" viewBox="0 0 760 150" role="img" aria-label="RSI simple de 14 cambios, escala de 0 a 100">${[0,30,70,100].map(v=>`<line x1="76" x2="740" y1="${125-v}" y2="${125-v}" stroke="#cfd9d3" stroke-dasharray="4 3"/><text x="65" y="${129-v}" text-anchor="end">${v}</text>`).join('')}<path data-study="rsi" d="${path('rsi',v=>125-v)}" fill="none" stroke="#665ac7" stroke-width="2"/></svg></div>`:''}
 <p class="muted">${style==='candles'?'Velas de referencias: primero, máximo, mínimo y último valor diario publicado en cada semana o mes. No son apertura/cierre ni extremos intradía de mercado. Los grupos de los extremos pueden estar incompletos.':interval==='daily'?'Cada punto representa una observación publicada. El eje horizontal respeta el tiempo transcurrido.':'Cada punto muestra la última referencia publicada del grupo.'} ${market?'Indicadores calculados sobre observaciones diarias antes de agrupar; cambiar la escala no cambia su fórmula.':''}</p>
 ${enabled.length?`<p class="econ-legend">${enabled.map(k=>`<span style="color:${colors[k]||'#52645f'}">${esc(studies[k])}</span>`).join('')}</p><p class="muted">Media/EMA/bandas requieren 20 o 50 observaciones previas; RSI, 15. Los tramos sin historial suficiente no se dibujan.</p><details><summary>Fórmulas de los indicadores del gráfico</summary><p>Media: promedio aritmético de las últimas 20 o 50 observaciones. EMA 20: semilla de media 20 y factor 2/21. Bandas: media 20 ± dos desviaciones estándar poblacionales. RSI simple: ganancias/pérdidas de 14 cambios, sin suavizado Wilder; 50 si no hay cambios. No son predicciones.</p></details>`:''}
 ${style==='candles'?`<details><summary>Ver referencias de las velas</summary><div class="econ-table"><table><thead><tr><th>Desde / hasta</th><th>Primera</th><th>Máxima</th><th>Mínima</th><th>Última</th><th>N</th></tr></thead><tbody>${buckets.slice().reverse().map(b=>`<tr><td>${esc(b.start)} / ${esc(b.date)}</td>${[b.open,b.high,b.low,b.close].map(v=>`<td>${numberLabel(v,d.id)}</td>`).join('')}<td>${b.count}</td></tr>`).join('')}</tbody></table></div></details>`:''}`;
}
